import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.Cdp8-jB6.js";const h=JSON.parse('{"title":"RFC-029 — Image staging ground · fetch→stage→approve→promote (v0.7)","description":"","frontmatter":{},"headers":[],"relativePath":"rfc/RFC-029.md","filePath":"rfc/RFC-029.md"}'),i={name:"rfc/RFC-029.md"};function s(d,e,n,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="rfc-029-—-image-staging-ground-·-fetch→stage→approve→promote-v0-7" tabindex="-1">RFC-029 — Image staging ground · fetch→stage→approve→promote (v0.7) <a class="header-anchor" href="#rfc-029-—-image-staging-ground-·-fetch→stage→approve→promote-v0-7" aria-label="Permalink to &quot;RFC-029 — Image staging ground · fetch→stage→approve→promote (v0.7)&quot;">​</a></h1><blockquote><p>Status · Shipped (2026-06-27) Date · 2026-06-24 Target · v0.7 Tracked by · GH issue #363</p></blockquote><blockquote><p><strong>Why this is an RFC.</strong> <code>/credits</code> is supposed to be the honest bill-of-materials for the imagery Orrery ships. Today it lists <strong>every</strong> downloaded image — <code>image-provenance.json</code> has 3,512 entries with zero display filtering, so ~828 vision-rejected images (and an unknown number of orphans) are credited <em>and shipped</em> despite never rendering. Fixing the credits page alone leaves the rejected files in the deployed bundle (bloat + distributing CC-BY assets we don&#39;t credit-in-context). The durable fix changes the pipeline&#39;s <em>shape</em>: downloads land in a staging ground, only approved images reach the shipped tree, and provenance walks the shipped tree only. That&#39;s an architecture change across the fetchers, the provenance build, the deploy/docker steps, and a one-time migration — locked here before the slices start.</p></blockquote><p><strong>Gating sentence</strong>: Locks the image staging-ground pipeline — <code>static/images/_staging/</code> (gitignored) receives every new fetch, vision scores it, a human approval in <code>/dev</code> promotes it to the shipped <code>static/images/</code> tree, <code>build-image-provenance.ts</code> walks the shipped tree only so <code>/credits</code> == shipped == displayed, build/deploy/docker prune <code>_staging/</code>, rejected assets stay in staging behind an image-tool hard-prune, and a one-time migration relocates today&#39;s vision-rejected-and-undisplayed images out of the shipped tree — tracked by <a href="https://github.com/chipi/orrery/issues/363" target="_blank" rel="noreferrer">issue #363</a>.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p><code>credited == shipped == displayed</code>. A new image cannot reach the deployed bundle (or <code>/credits</code>) without passing curation and an explicit human promote; rejected images are quarantined in a gitignored staging ground, never shipped, never credited, recoverable, and hard-prunable on demand.</p><h2 id="scope-v0-7" tabindex="-1">Scope (v0.7) <a class="header-anchor" href="#scope-v0-7" aria-label="Permalink to &quot;Scope (v0.7)&quot;">​</a></h2><ul><li><code>static/images/_staging/</code> staging ground (gitignored) + the fetch / score / promote flow.</li><li><code>build-image-provenance.ts</code> walks the shipped tree only (skips <code>_staging/</code>).</li><li>Build/deploy/docker exclude <code>_staging/</code>.</li><li>One-time migration of the current corpus&#39;s undisplayed rejects into staging.</li><li>Image-tool <code>prune-staging</code> (hard delete) option.</li></ul><h2 id="non-goals-v0-7" tabindex="-1">Non-goals (v0.7) <a class="header-anchor" href="#non-goals-v0-7" aria-label="Permalink to &quot;Non-goals (v0.7)&quot;">​</a></h2><ul><li>Re-curating the existing displayed corpus. <strong>Anything linked/displayed today is auto-approved</strong> and stays in the shipped tree untouched (decision 2).</li><li>Changing the vision-scoring model or thresholds (<code>score-images.ts</code> unchanged).</li><li>A new public review UI — promotion drives off the existing <code>/dev</code> curation surface.</li></ul><h2 id="survey-—-verified-current-state-2026-06-24" tabindex="-1">Survey — verified current state (2026-06-24) <a class="header-anchor" href="#survey-—-verified-current-state-2026-06-24" aria-label="Permalink to &quot;Survey — verified current state (2026-06-24)&quot;">​</a></h2><ul><li><code>image-provenance.json</code>: <strong>3,512 entries</strong>, built by <code>build-image-provenance.ts</code> walking every on-disk file under <code>static/images/**</code> (curated walkers + a <code>direct-other</code> fallback). No display/approval field.</li><li><code>/credits</code> (<code>src/routes/credits/+page.svelte</code>): renders <code>provenance.entries</code> verbatim — <strong>no vision/rejection/displayed filter</strong>.</li><li><code>image-vision.json</code>: 2,066 scored → <strong>1,238 approved (<code>rejected_by == null</code>)</strong>, <strong>828 rejected</strong> (374 score-below-threshold, 276 category-diagram, 178 category-people). The UI pickers honor rejection; <code>/credits</code> does not.</li><li><code>image-curation.json</code>: empty / unwired.</li><li>~1,446 provenance entries are unscored (logos, SVG diagrams, the flat-family covers/heroes, textures, panoramas) — <strong>legitimately used</strong>; they must stay.</li><li><code>adapter-static</code> copies all of <code>static/</code> into <code>build/</code>; docker&#39;s nginx serves the host <code>build/</code>. So excluding staging from deploy needs a post-build prune (or staging never committed + pruned anyway).</li><li>Existing pruning machinery to lean on: <code>scripts/prune-orphan-images.ts</code>, <code>scripts/prune-image-slots.ts</code>.</li></ul><h2 id="decisions-locked-with-marko" tabindex="-1">Decisions (locked with Marko) <a class="header-anchor" href="#decisions-locked-with-marko" aria-label="Permalink to &quot;Decisions (locked with Marko)&quot;">​</a></h2><ol><li><strong>Staging is gitignored</strong> — unapproved downloads never bloat the repo; only the shipped tree is version-controlled. Trade-off: rejects aren&#39;t preserved across machines, but they&#39;re re-fetchable.</li><li><strong>Forward policy:</strong> vision-score → staging; <strong>human approve in <code>/dev</code> → promote</strong> to the shipped tree. The policy is <strong>not</strong> retro-applied — every image linked/displayed in the current corpus is auto-approved and left in place.</li><li><strong>Rejected images stay in staging</strong> for re-review; an image-tool <strong><code>prune-staging</code></strong> option hard-deletes them when the curator decides.</li><li><strong>Durable approved allowlist</strong> — <code>static/data/image-approved.json</code> is the <strong>sticky source of truth</strong> for &quot;used/approved,&quot; independent of vision scores. <code>/credits</code> + provenance derive from it; re-running provenance (new files, walk changes, re-scores) <strong>can never drop an approved image</strong>. A human approve appends; entries are never auto-removed. This is the answer to &quot;don&#39;t accidentally drop a used image.&quot;</li><li><strong>Manual approve / skip / prune</strong> — the image-tool reviews the staging folder and lets a human <strong>approve</strong> any image (→ moves to main + appended to the allowlist), <strong>skip</strong> it (leave staged), or <strong>prune</strong> staging (hard delete) — manual approval overrides vision regardless of score.</li></ol><h2 id="image-approved-json-—-the-durable-source-of-truth" tabindex="-1">image-approved.json — the durable source of truth <a class="header-anchor" href="#image-approved-json-—-the-durable-source-of-truth" aria-label="Permalink to &quot;image-approved.json — the durable source of truth&quot;">​</a></h2><p>Shape: <code>{ version, generated_by, note, count, approved: string[] }</code> — every approved/used image path. <strong>Derived (not hand-frozen)</strong> by <code>scripts/audit-image-usage.ts --write-approved</code>: the allowlist is exactly the set of shipped images the usage audit certifies as displayed (referenced in <code>static/data</code>/<code>src</code>, within a gallery count-cap, a hero slot, a body surface, a hotspot tier, or a card). Re-derive after fetches land; because the audit only ever certifies <em>used</em> images and human-approves append, a re-derive can never drop a still-displayed image. Provenance and <code>/credits</code> are an <strong>intersection</strong> of (on-disk shipped tree) ∩ (approved list) so neither a stale walk nor a re-score can drop a used image.</p><p><strong>Empirical finding from the migration (2026-06-24):</strong> the displayed corpus was already ~99.9% honest. &quot;Vision-rejected&quot; never controlled gallery display — gallery <em>count-caps</em> do — so the ~828 vision-rejected images that show in <code>/credits</code> are, with rare exception, legitimately displayed. The audit found only <strong>7 true orphans</strong> (surface-gallery slots above their count-cap: <code>mars-sites/mangalyaan</code> 06–07, <code>mars-sites/mars-express</code> 06, <code>moon-sites/apollo15</code> 06–09); these were staged out. The lasting value of this RFC is therefore the <strong>forward</strong> staging flow + the durable allowlist + the committed audit gate, not a mass relocation.</p><h2 id="slice-plan-—-✅-shipped-2026-06-27" tabindex="-1">Slice plan — ✅ SHIPPED (2026-06-27) <a class="header-anchor" href="#slice-plan-—-✅-shipped-2026-06-27" aria-label="Permalink to &quot;Slice plan — ✅ SHIPPED (2026-06-27)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Slice</th><th>Work</th><th>Status</th></tr></thead><tbody><tr><td>1</td><td><code>static/images/_staging/</code> + <code>.gitignore</code>; <code>build-image-provenance.ts</code> skips <code>_staging/</code></td><td>✅ <code>b1488b8d7</code></td></tr><tr><td>—</td><td><strong>Decision 4</strong> — build-provenance intersects <code>image-approved.json</code> (scoped to <code>/images/</code>; logos/textures bypass); <code>/credits</code> derives from the allowlist</td><td>✅ <code>fa5f1847e</code></td></tr><tr><td>2</td><td><strong>Migration</strong> — moot: audit proved the corpus was ~99.9% honest; only the structural mars-site orphans were staged out (no mass relocation)</td><td>✅ (folded into reconciliation)</td></tr><tr><td>3</td><td>Fetchers stage by default — <code>scripts/lib/staging.ts</code> <code>toStagingDest()</code> redirects gallery-slot writes in <code>fetch-assets.ts</code>; gallery-count writes skipped when staging; <code>--no-stage</code> opt-out</td><td>✅ <code>202327ff0</code></td></tr><tr><td>4 + 5 (Decision 5)</td><td><code>/dev/staging</code> review surface (rich grid, filters, bulk-mark) + <code>api/+server.ts</code> &quot;Apply marked actions&quot; → promote (move + append allowlist + bump contiguous gallery count) / prune</td><td>✅ <code>6b3eee98e</code></td></tr><tr><td>5</td><td>Deploy prune: post-<code>vite build</code> <code>scripts/prune-build-staging.mjs</code> rm&#39;s <code>build/images/_staging</code> + asserts none survives</td><td>✅ <code>0a91d6d63</code></td></tr><tr><td>6</td><td>Hard-delete: the <code>/dev/staging</code> <strong>Prune</strong> action (no separate CLI needed)</td><td>✅ <code>6b3eee98e</code></td></tr></tbody></table><p><strong>Notes vs the original plan:</strong> promote + prune are one &quot;Apply marked actions&quot; POST in the review surface (no separate <code>promote-images.ts</code> / <code>prune-staging</code> CLIs). Decision 4&#39;s intersection is scoped to <code>/images/</code> so <code>/logos/</code> + <code>/textures/</code> (never staged) stay credited. Promote bumps each id&#39;s gallery count to its <strong>contiguous</strong> main-slot count, keeping galleries gap-free. Crediting a promoted image still needs <code>npm run build-image-provenance</code> (use <code>--offline</code> to skip Wikimedia).</p><h2 id="migration-—-the-safe-move-list-slice-2" tabindex="-1">Migration — the safe move-list (Slice 2) <a class="header-anchor" href="#migration-—-the-safe-move-list-slice-2" aria-label="Permalink to &quot;Migration — the safe move-list (Slice 2)&quot;">​</a></h2><p>Move = <code>image-vision</code> <code>rejected_by != null</code> <strong>AND not displayed</strong>, where <em>displayed</em> means referenced by an explicit display path. Guards:</p><ul><li><strong>Exclude hero slots</strong> (<code>…/01.jpg</code> + variants) — heroes, never moved.</li><li><strong>Exclude images explicitly path-referenced</strong> in <code>static/data/**</code> <em>excluding the manifests themselves</em> (<code>image-vision.json</code>, <code>image-provenance.json</code>, <code>image-curation.json</code>, <code>*-galleries.json</code> count maps). The first naive pass scanned the manifests and matched everything → 0 to move; the corrected pass scans only display-reference files (hero-overrides resolved to paths, science <code>photo.src</code>, surface-site photo refs).</li><li>Output a dry-run report (count + MB) under <code>docs/provenance/</code> and require eyeball sign-off before the move.</li></ul><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h2><ul><li><strong>False-move</strong> (relocating a displayed image): mitigated by the explicit-reference guard + slot-01 guard + dry-run sign-off + in-browser gallery check after the move.</li><li><strong>Deploy leak</strong> (staging shipped): mitigated by gitignore <em>and</em> the post-build prune (belt + suspenders).</li><li><strong>Cross-machine fetch divergence</strong> (staging gitignored): acceptable — staging is local curation scratch; CI/cron fetchers stage then promote within the same run.</li></ul><h2 id="acceptance" tabindex="-1">Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;Acceptance&quot;">​</a></h2><ul><li><code>/credits</code> entry count == images actually rendered (no vision-rejected, no orphans).</li><li><code>grep -r _staging build/</code> is empty after a production build.</li><li>A new fetch lands in <code>_staging/</code> and cannot reach <code>build/</code> without <code>promote-images.ts</code>.</li><li>Each slice independently revertable + browser/validate-verified.</li></ul><h2 id="open-questions-carried-into-the-slices" tabindex="-1">Open questions (carried into the slices) <a class="header-anchor" href="#open-questions-carried-into-the-slices" aria-label="Permalink to &quot;Open questions (carried into the slices)&quot;">​</a></h2><ul><li>Does <code>promote-images.ts</code> drive purely off an <code>/dev</code>-written approval list, or also auto-promote vision-approved on first score? (Lean: explicit approval only, per decision 2.)</li><li>Should <code>prune-staging</code> also drop the corresponding <code>image-vision.json</code> entries, or keep the scores for re-fetch dedupe? (Lean: keep scores; content-hash cache already dedupes.)</li></ul>',29)])])}const u=o(i,[["render",s]]);export{h as __pageData,u as default};
